#include "../../apps/openmw/ios/openmw_ios_touch_state.hpp"
#include <cassert>
#include <limits>
using namespace OpenMWIOS::Touch;
int main(){auto l=makeLayout(844,390,{0,47,21,47});EditorPinch p;int i=int(Action::Attack);auto before=l.buttons[i].bounds;assert(!p.begin(false,i,l));assert(!p.begin(true,-1,l));assert(!p.begin(true,int(Action::Parry),l));assert(p.begin(true,i,l));p.update(l,1.2);assert(l.buttons[i].bounds.radius>=before.radius);p.update(l,std::numeric_limits<float>::quiet_NaN());p.finish(l,true);assert(l.buttons[i].bounds.radius==before.radius);assert(l.buttons[i].bounds.center.x==before.center.x);assert(!p.active());p.begin(true,i,l);p.update(l,100);assert(l.buttons[i].bounds.radius<=safeShortSide(l)*.24f);p.update(l,.001);assert(l.buttons[i].bounds.radius==18);p.finish(l,false);auto profile=profileFromLayout(l);profile.customized=true;auto copy=makeLayout(844,390,{0,47,21,47});applyProfile(copy,profile);assert(copy.buttons[i].bounds.radius==18);auto movement=l.movementRadius;p.begin(true,int(ActionCount),l);p.update(l,100);assert(l.movementRadius<=safeShortSide(l)*.24f);p.finish(l,true);assert(l.movementRadius==movement);ProfileEditor editor;editor.begin(profile);auto altered=profile;altered.buttons[i].radius=.15f;editor.finish(false,altered);assert(altered.buttons[i].radius==profile.buttons[i].radius);}
